// INF-39: Alert on hung Builder (>4h) or Tester (>2h) tasks
const MC_API = 'http://localhost:3000/api/issues';
const TELEGRAM_USER = '5084875115';
const ALERTS_CHANNEL = '1485333335868834063'; // #alerts

const BUILDER_TIMEOUT_H = 4;
const TESTER_TIMEOUT_H = 2;

const staticData = this.getWorkflowStaticData('global');
if (!staticData.alertedTasks) staticData.alertedTasks = {};

const now = Date.now();
// Prune after 24h (re-alert if still stuck)
for (const [key, ts] of Object.entries(staticData.alertedTasks)) {
  if (now - ts > 24 * 60 * 60 * 1000) delete staticData.alertedTasks[key];
}

const {execSync} = require('child_process');
const alerts = [];

let allIssues;
try {
  allIssues = await helpers.httpRequest({
    method: 'GET',
    url: MC_API,
    headers: { 'Content-Type': 'application/json' }
  });
} catch(e) {
  return [{ json: { error: String(e) } }];
}

// Builder tasks in_progress >4h
const builderTasks = allIssues.filter(i =>
  i.assignee === 'builder' &&
  i.status === 'in_progress' &&
  i.started_at
);

for (const task of builderTasks) {
  const startedAt = new Date(task.started_at).getTime();
  const ageH = (now - startedAt) / (60 * 60 * 1000);

  if (ageH < BUILDER_TIMEOUT_H) continue;
  if (staticData.alertedTasks['b:' + task.id]) continue;

  alerts.push({
    type: 'builder',
    task_key: task.task_key,
    title: task.title,
    age_hours: Math.round(ageH)
  });
  staticData.alertedTasks['b:' + task.id] = now;
}

// Tester tasks in in_review >2h
const testerTasks = allIssues.filter(i =>
  i.assignee === 'tester' &&
  i.status === 'in_review' &&
  i.submitted_at
);

for (const task of testerTasks) {
  const submittedAt = new Date(task.submitted_at).getTime();
  const ageH = (now - submittedAt) / (60 * 60 * 1000);

  if (ageH < TESTER_TIMEOUT_H) continue;
  if (staticData.alertedTasks['t:' + task.id]) continue;

  alerts.push({
    type: 'tester',
    task_key: task.task_key,
    title: task.title,
    age_hours: Math.round(ageH)
  });
  staticData.alertedTasks['t:' + task.id] = now;
}

if (alerts.length > 0) {
  const builderAlerts = alerts.filter(a => a.type === 'builder');
  const testerAlerts = alerts.filter(a => a.type === 'tester');

  let msg = '\u26a0\ufe0f Agent Timeout Alert\n\n';
  if (builderAlerts.length > 0) {
    msg += `\ud83d\udc77 Builder stuck (>${BUILDER_TIMEOUT_H}h):\n`;
    builderAlerts.forEach(a => msg += `\u2022 ${a.task_key}: ${a.title.slice(0, 60)} (${a.age_hours}h)\n`);
  }
  if (testerAlerts.length > 0) {
    msg += `\n\ud83e\uddea Tester stuck (>${TESTER_TIMEOUT_H}h):\n`;
    testerAlerts.forEach(a => msg += `\u2022 ${a.task_key}: ${a.title.slice(0, 60)} (${a.age_hours}h)\n`);
  }

  try {
    execSync('openclaw message send --channel telegram --target ' + TELEGRAM_USER + ' --message ' + JSON.stringify(msg) + ' 2>/dev/null', {timeout: 15000, stdio: 'pipe'});
  } catch(e) {}

  try {
    execSync('openclaw message send --channel discord --target channel:' + ALERTS_CHANNEL + ' --message ' + JSON.stringify(msg) + ' 2>/dev/null', {timeout: 15000, stdio: 'pipe'});
  } catch(e) {}
}

return [{ json: {
  alerts_count: alerts.length,
  alerts,
  timestamp: new Date().toISOString()
} }];
